#ifndef WOTM_VU0_NATIVE_H
#define WOTM_VU0_NATIVE_H

#include "runtime/ps2_vu1.h"

#include <cstddef>
#include <cstdint>

// A VU0 microprogram in C++ (generated by tools/vu0native.py): takes the state already copied from the EE context and VU0 data
// memory, and leaves state and memory as the interpreter would at the end of the program (including pc, cycles and flags).
using WotmVu0Fn = void (*)(VU1State &state, uint8_t *vu0Data);

struct WotmVu0Program
{
    uint32_t start;       // entry pc (bytes)
    uint32_t hashStart;   // start of the range checked by the hash (every pair the program can execute)
    uint32_t length;      // byte length of that range
    uint64_t hash;     // FNV-1a 64 of those bytes
    WotmVu0Fn fn;
};

// Native version of the program at pc, or nullptr (no native version, code differs from what's expected, or WOTM_VU0_INTERP is set).
WotmVu0Fn wotmVu0NativeLookup(const uint8_t *vu0Code, uint32_t codeSize, uint64_t generation, uint32_t pc);
// 4096-byte image of the VU0 code memory that the ELF's packet leaves behind (hierLoadVu0Ucode sends it through VIF0), or nullptr
// if the .gen.inc predates it. The game executable copies it directly, without VIF0 (FRONTEIRA.md, step 7).
const uint8_t *wotmVu0CodeImage();
// Runs with the VU's rounding mode (toward zero).
void wotmVu0NativeRun(WotmVu0Fn fn, VU1State &state, uint8_t *vu0Data);

#endif
